import {helpers,acceptsAnswer,helperLimit} from './help-content.mjs';
import {currentVisit} from './garden-core.mjs';
import {storyNodes} from './story-content.mjs';
import {guideRail} from './garden-ui.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function modelView(h,d){
 const m=h.model,spot=(label,i)=>`<button type="button" class="helper-tile ${d.spotlight===i?'selected':''}" data-help-spot="${i}" aria-pressed="${d.spotlight===i}">${label}</button>`;
 if(m.type==='text')return `<p class="tiny">Tap either part to give it a spotlight.</p><div class="helper-text">${m.segments.map((t,i)=>spot(esc(t),i)).join('')}</div>${d.spotlight!==null?`<p class="model-readout" aria-live="polite">${esc(m.clue)}</p>`:''}`;
 if(m.type==='menu')return `<p>Wishes: <strong>${m.wanted.map(esc).join(' and ')}</strong>.</p><p class="tiny">Tap a dish to check its properties.</p><div class="helper-menu">${m.items.map((t,i)=>spot(`<strong>${esc(t.name)}</strong><span>${t.properties.map(esc).join(' · ')}</span>`,i)).join('')}</div>${d.spotlight!==null?`<p class="model-readout" aria-live="polite">${esc(m.items[d.spotlight].name)}: ${m.wanted.every(p=>m.items[d.spotlight].properties.includes(p))?'fits both wishes.':'does not fit both wishes.'}</p>`:''}`;
 if(m.type==='compare')return `<p class="tiny">Tap a row to look at its count.</p><div class="helper-comparison">${m.labels.map((label,i)=>spot(`${esc(label)}<span class="helper-dots" aria-hidden="true">${'● '.repeat(m.counts[i])}</span><strong>${m.counts[i]}</strong>`,i)).join('')}</div>${d.spotlight!==null?`<p class="model-readout" aria-live="polite">${esc(m.labels[d.spotlight])}: ${m.counts[d.spotlight]}.</p>`:''}`;
 const limit=helperLimit(h);
 const controls=`<div class="summary-links"><button class="secondary" id="help-step" ${d.steps===limit?'disabled':''}>${m.type==='array'?'Count the next row':'Count the next space'}</button><button class="text-button" id="help-recount">Count again</button></div>`;
 if(m.type==='array')return `<div class="helper-array" role="img" aria-label="${m.rows} rows of ${m.cols} counters; ${d.steps} ${d.steps===1?'row':'rows'} counted">${Array.from({length:m.rows},(_,i)=>`<div class="helper-row ${i<d.steps?'counted':''}">${'<span></span>'.repeat(m.cols)}</div>`).join('')}</div><p class="model-readout" aria-live="polite">${d.steps} ${d.steps===1?'row':'rows'} counted: ${d.steps*m.cols} counters.</p>${controls}`;
 const x=i=>24+i/m.max*360;
 return `<svg class="helper-ruler" viewBox="0 0 410 110" role="img" aria-label="Ribbon from ${m.start} to ${m.end} centimetres. ${d.steps} spaces counted."><rect x="${x(m.start)}" y="12" width="${x(m.end)-x(m.start)}" height="22" fill="#da8d8d"/>${Array.from({length:limit},(_,i)=>`<rect x="${x(m.start+i)}" y="42" width="${360/m.max}" height="17" fill="${i<d.steps?'#e9b84a':'#eaf4ef'}" stroke="#397958"/>`).join('')}<path d="M24 66H384" stroke="#183f39"/>${Array.from({length:m.max+1},(_,i)=>`<text x="${x(i)}" y="94" text-anchor="middle" font-size="15">${i}</text>`).join('')}</svg><p class="model-readout" aria-live="polite">${d.steps} one-centimetre ${d.steps===1?'space':'spaces'} counted.</p>${controls}`;
}
export function helpPage(state,d){
 const v=currentVisit(state),n=storyNodes[v.node],h=helpers[v.node],x=d.helper,correct=acceptsAnswer(h,x.attempts.at(-1));
 return `<div class="page-heading"><a class="back" href="#home">← Pause in the garden</a><p class="place-name">A little help, at your pace</p><h1>${esc(h.title)}</h1><p>Your question “${esc(n.title)}” is waiting. This is a different, smaller example.</p></div><div class="story-layout"><article class="story-sheet helper-sheet"><p class="story-body">${esc(h.lesson)}</p><section class="helper-model" aria-label="Explore the example">${modelView(h,x)}</section><p class="story-question">${esc(h.prompt)}</p><form id="help-answer-form" novalidate>${h.kind==='choice'?`<div class="choices">${h.choices.map((c,i)=>`<button type="button" class="choice ${x.choice===i?'selected':''}" data-help-choice="${i}" aria-pressed="${x.choice===i}">${esc(c)}</button>`).join('')}</div>`:`<label for="help-answer">Your example answer</label><div class="answer-line"><input id="help-answer" inputmode="numeric" autocomplete="off" value="${esc(x.input)}" aria-describedby="help-error"></div>`}<button class="primary" type="submit">Try the example</button><p id="help-error" role="alert">${esc(x.error||'')}</p></form><div id="help-feedback" aria-live="polite">${x.attempts.length?`<p class="feedback ${correct?'success':''}">${correct?'That fits this example. You can return whenever you like.':'We can look again, try another idea, or think it through together.'}</p>`:''}</div>${!x.revealed?'<button class="text-button" id="help-explain">Think through this example</button>':`<div class="solution"><p>${esc(h.explanation)}</p></div>`}<div class="next-row"><button class="primary" id="help-return">Return to my question</button><a class="text-button" href="#home">Pause here</a></div><button class="text-button" id="help-skip">Leave the waiting question for now</button><p class="tiny">This example is support. It does not answer or finish your waiting question.</p></article>${guideRail(state,'{guide} says, “We can try a smaller example together. There’s no hurry, and you can return whenever you’re ready.”')}</div>`;
}
